INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('agenda_comercial','pantalla','agenda_comercial','Agenda Comercial','Calendario de reuniones y visitas del equipo comercial.','["src/pages_core.jsx#AgendaComercial"]'::jsonb,'37a93e9e93')
