INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inventario_admin','pantalla','inventario','Almacenes','Existencias, entradas, ajustes, transferencias y conteos del almacén desde Administración.','["src/pages_extra.jsx#Inventario"]'::jsonb,'71bf749470')
